style.css:
@-moz-document domain("youtube.com") {
:root,
html[dark],
[dark] {
    --dracula-background: #282A36;
    --dracula-current-line: #44475A;
    --dracula-selection: #44475A;
    --dracula-foreground: #F8F8F2;
    --dracula-comment: #6272A4;
    --dracula-red: #FF5555;
    --dracula-orange: #FFB86C;
    --dracula-yellow: #F1FA8C;
    --dracula-green: #50FA7B;
    --dracula-cyan: #8BE9FD;
    --dracula-purple: #BD93F9;
    --dracula-pink: #FF79C6;

    --yt-spec-base-background: var(--dracula-background);
    --yt-spec-raised-background: var(--dracula-background);
    --yt-spec-menu-background: var(--dracula-current-line);
    --yt-spec-general-background-a: var(--dracula-background);
    --yt-spec-general-background-b: var(--dracula-background);
    --yt-spec-general-background-c: var(--dracula-background);
    --paper-dialog-background-color: var(--dracula-current-line);
    --ytd-searchbox-background: hsl(0, 0%, 7%);

    --yt-spec-text-primary: var(--dracula-foreground);
    --yt-spec-text-primary-inverse: var(--dracula-background);
    --yt-spec-text-secondary: var(--dracula-comment);
    --yt-spec-text-disabled: #606060;
    --ytd-searchbox-text-color: var(--dracula-foreground);
    --paper-input-container-input-color: var(--dracula-foreground);

    --yt-spec-icon-active-other: var(--dracula-foreground);
    --yt-spec-icon-inactive: var(--dracula-comment);
    --yt-spec-icon-disabled: #606060;

    --yt-spec-call-to-action: var(--dracula-purple);
    --yt-spec-call-to-action-inverse: var(--dracula-purple);
    --yt-spec-brand-icon-active: var(--dracula-pink);
    --yt-spec-themed-blue: var(--dracula-cyan);
    --yt-spec-themed-green: var(--dracula-green);
    --yt-spec-static-brand-red: var(--dracula-red);
    --paper-checkbox-checked-color: var(--dracula-purple);
    --paper-radio-button-checked-color: var(--dracula-purple);
    --paper-toggle-button-checked-button-color: var(--dracula-purple);

    --yt-spec-outline: rgba(248, 248, 242, 0.2);
    --ytd-searchbox-border-color: var(--dracula-current-line);
    --ytd-searchbox-legacy-border-color: var(--dracula-current-line);

    --yt-spec-badge-chip-background: var(--dracula-selection);
    --yt-spec-button-chip-background-hover: var(--dracula-current-line);
    --yt-spec-additive-background: rgba(248, 248, 242, 0.1);

    scrollbar-color: var(--dracula-comment) var(--dracula-background);
}

* {
    transition: transform 0.2s ease-in-out, background-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out, border-color 0.2s ease-in-out;
}

yt-button-shape,
ytd-guide-entry-renderer,
yt-chip-cloud-chip-renderer,
ytd-playlist-panel-video-renderer,
.yt-lockup-view-model {
    transition: transform 0.15s ease-in-out, background-color 0.2s ease-in-out;
}

yt-button-shape:hover,
ytd-guide-entry-renderer:hover,
yt-chip-cloud-chip-renderer:hover,
ytd-playlist-panel-video-renderer:hover,
.yt-lockup-view-model:hover {
    transform: scale(1.03);
}

yt-button-shape:active,
ytd-guide-entry-renderer:active,
yt-chip-cloud-chip-renderer:active,
ytd-playlist-panel-video-renderer:active {
    transform: scale(0.97);
    transition-duration: 0.05s;
}

ytd-thumbnail:hover {
    transform: scale(1.05);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
    z-index: 10;
}

tp-yt-iron-overlay-backdrop,
#frosted-glass.ytd-app,
#cinematics {
    display: none !important;
}

ytd-app::before,
ytd-app::after,
#guide-content.ytd-app::after,
ytd-post-renderer[uses-compact-lockup]:after {
    content: "" !important;
}

ytd-mini-guide-renderer,
tp-yt-iron-overlay-backdrop {
    backdrop-filter: blur(10px) !important;
    background: rgba(40, 42, 54, 0.8) !important;
}

body {
    background: var(--dracula-background) !important;
}

.ytp-play-progress,
.ytp-swatch-background-color {
    background: linear-gradient(to right, #FF79C6 80%, #BD93F9 100%) !important;
}

.ytp-volume-slider-handle::before {
    background-color: var(--dracula-pink) !important;
}

yt-formatted-string.ytd-subscribe-button-renderer {
    color: var(--dracula-background) !important;
}

#progress.ytd-app {
    background: var(--dracula-red) !important;
}

ytd-live-chat-frame #author-name[type="owner"],
yt-live-chat-author-chip[is-owner] #author-name {
    color: var(--dracula-yellow) !important;
}

ytd-live-chat-frame #author-name[type="moderator"] {
    color: var(--dracula-cyan) !important;
}

ytd-live-chat-frame #author-name[type="member"] {
    color: var(--dracula-green) !important;
}

a.yt-simple-endpoint.yt-formatted-string {
    color: var(--dracula-cyan);
}

a.yt-simple-endpoint.yt-formatted-string:hover {
    color: var(--dracula-pink);
}

ytd-mini-guide-renderer {
    background-color: rgba(40, 42, 54, 0.8) !important;
    backdrop-filter: blur(10px) !important;
    border: 2px solid var(--dracula-selection);
    border-radius: 20px;
    padding: 8px 0;
    margin: 60px 0 5px 5px;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
}

ytd-mini-guide-entry-renderer[system-icons] .title.ytd-mini-guide-entry-renderer {
    display: none;
}

ytd-mini-guide-renderer:hover {
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

ytd-app[frosted-glass-exp] tp-yt-app-drawer.ytd-app[persistent] {
    background-color: rgba(40, 42, 54, 0.8) !important;
    backdrop-filter: blur(10px) !important;
    border: 2px solid var(--dracula-selection);
    border-radius: 20px;
    padding-top: 8px;
    margin: 5px;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out !important;
}

ytd-app[frosted-glass-exp] tp-yt-app-drawer.ytd-app[persistent]:hover {
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

#guide-inner-content.ytd-app::-webkit-scrollbar {
    width: 0;
}

#guide-inner-content.ytd-app {
    scrollbar-width: none;
}

#frosted-glass.with-chipbar.ytd-app {
    background-color: var(--dracula-background) !important;
    backdrop-filter: none !important;
}

#content.ytd-rich-item-renderer {
    height: 100%;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    margin-left: 10px;
}

.yt-spec-button-shape-next--mono.yt-spec-button-shape-next--text {
    color: var(--dracula-cyan);
}

.ytChipShapeActive {
    border-radius: 15px 0px 15px 0px;
    color: #F1FA8C !important;
    background-color: var(--dracula-background);
    border: 2px solid var(--dracula-selection);
    font-family: monospace;
}

.ytChipShapeChip {
    border-radius: 15px 0px 15px 0px;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out !important;
}

#endpoint.yt-simple-endpoint.ytd-guide-entry-renderer {
    color: #F1FA8C !important;
}

.ytChipShapeChip:hover {
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

[active] {
    border-radius: 15px 0px 15px 0px;
}

ytd-guide-entry-renderer:not([active]):hover {
    background-color: var(--dracula-current-line) !important;
    border-radius: 15px 0px 15px 0px;
}

.ytSearchboxComponentInputBox.ytSearchboxComponentInputBoxDark {
    background: var(--dracula-current-line) !important;
}

.ytThumbnailOverlayProgressBarHostWatchedProgressBarSegment {
    background: linear-gradient(to right, #FF79C6 80%, #BD93F9 100%) !important;
}

.ytp-scrubber-button {
    background-color: var(--dracula-purple) !important;
}

#progress {
    background: linear-gradient(to right, #FF79C6 80%, #BD93F9 100%) !important;
}

ytd-playlist-panel-video-renderer:hover {
    background-color: var(--dracula-current-line);
    border-radius: 15px 0px 15px 0px;
}

ytd-playlist-panel-video-renderer[selected][use-color-palette],
ytd-playlist-panel-video-renderer[selected][use-color-palette]:hover:not(.dragging) {
    background-color: #6272A4;
    border-radius: 15px 0px 15px 0px;
    color: var(--dracula-cyan) !important;
    border: 2px solid var(--dracula-selection);
    font-family: monospace;
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

ytd-playlist-panel-video-renderer[selected] #video-title {
    color: var(--dracula-cyan) !important;
}

ytd-playlist-panel-renderer[collapsible][collapsed][use-color-palette] .header.ytd-playlist-panel-renderer {
    border-color: #FF79C6 !important;
    background-color: #6272A4;
}

ytd-masthead[frosted-glass-mode=without-chipbar] #background.ytd-masthead {
    backdrop-filter: blur(10px) !important;
    background: var(--dracula-background) !important;
}

.yt-spec-button-shape-next--size-m {
    background-color: var(--dracula-selection) !important;
    border-radius: 15px 3px 15px 3px;
    color: var(--dracula-cyan) !important;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out !important;
}

.yt-spec-button-shape-next--size-m:hover {
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

#masthead-container.ytd-app {
    background: var(--dracula-background) !important;
}

ytd-feed-filter-chip-bar-renderer[frosted-glass-mode=with-chipbar] #chips-wrapper.ytd-feed-filter-chip-bar-renderer {
    background-color: var(--dracula-background) !important;
}

.ytSearchboxComponentInputBoxDark {
    background-color: var(--dracula-selection) !important;
    border-radius: 15px 3px 0px 0px;
    color: var(--dracula-cyan) !important;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out !important;
}

.ytSearchboxComponentInputBoxDark:hover {
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

.ytSearchboxComponentSearchButtonDark {
    background-color: var(--dracula-selection) !important;
    border-radius: 0px 0px 15px 3px;
    color: var(--dracula-cyan) !important;
    transition: border-color 0.3s ease-in-out, box-shadow 0.3s ease-in-out !important;
}

.ytSearchboxComponentSearchButtonDark:hover {
    border-color: #FF79C6 !important;
    box-shadow: 0 0 12px rgba(255, 121, 198, 0.3) !important;
}

#logo-icon {
    background-image: url("https://github.com/CtorW/Youtube/blob/main/Yt-Dracula-data/Drac%23logo.png?raw=true") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    width: 90px !important;
    height: 30px !important;
}

#logo-icon svg {
    display: none !important;
}
}
